if(document.modelContext?.registerTool){const lifetime=new AbortController();window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});const tools=[{name:'read_current_roadbook',description:'Read current itinerary summary and selected day; no state changes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({summary:E.totals(plan,state),selected:getDay(),budget:E.budget(plan,state).total})},{name:'select_roadbook_day',description:'Select an existing itinerary day in the map and daily detail.',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:1}},required:['day'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.day)||input.day<1||input.day>plan.length)throw new Error('Day outside current itinerary');selectDay(plan[input.day-1].id,true);showView('route');return {selected:getDay()};}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{/* optional capability */}}
